public static UnitState inbetween(Frame frame1, Frame frame2, Unit unit1, Unit unit2, int step, int framesNumber) {
    Scene scene = frame1.getScene();
    int indexOf = scene.getIndexOf(frame1);
    float f = (step + 1.0f) / (framesNumber + 1.0f);
    Scene.AutoTweenRange autoTweenRangeOrNull = scene.tweens().findAutoTweenRangeForSpan(unit1.getName(), indexOf, indexOf + 1).orNull();
    if (autoTweenRangeOrNull != null) {
        Unit unitOrNull = scene.getFrameByIndex(autoTweenRangeOrNull.mFromFrame).findUnitByExactName(unit1.getName()).orNull();
        Unit unitOrNull2 = scene.getFrameByIndex(autoTweenRangeOrNull.mToFrame).findUnitByExactName(unit1.getName()).orNull();
        if (unitOrNull != null && unitOrNull2 != null) {
            float fMax = Math.max(0.0f, Math.min(1.0f, ((indexOf + f) - autoTweenRangeOrNull.mFromFrame) / (autoTweenRangeOrNull.mToFrame - autoTweenRangeOrNull.mFromFrame)));
            UnitState unitStateInbetweenStatesAt = InterpolatorFactory.inbetweenStatesAt(unitOrNull.mState, unitOrNull2.mState, Easing.sample(autoTweenRangeOrNull.mEasingType, fMax, autoTweenRangeOrNull.mEasingStrength));
            CameraMoveInterpolator.applyUnitShake(unitStateInbetweenStatesAt, unitOrNull.mState, unitOrNull2.mState, autoTweenRangeOrNull.mEasingType, autoTweenRangeOrNull.mEasingStrength, autoTweenRangeOrNull.mShakeFrequency, fMax);
            CameraMoveInterpolator.applyUnitCartwheel(unitStateInbetweenStatesAt, autoTweenRangeOrNull.mEasingType, autoTweenRangeOrNull.mEasingStrength, autoTweenRangeOrNull.mShakeFrequency, fMax);
            return unitStateInbetweenStatesAt;
        }
    }
    return InterpolatorFactory.inbetweenStates(unit1.mState, unit2.mState, step, framesNumber, Easing.EASING.NO, 0.5f);
}
